        $display("  SUMMARY TABLE");
        $display("============================================================");
        $display("  Pair  | Decision | Obstacles");
        $display("  ------|----------|----------");
        for (p = 1; p <= NUM_PAIRS; p = p + 1) begin
            if (pair_accept[p] == 1)
                $display("  %4d  | ACCEPT   | %0d", p, pair_obs[p]);
            else if (pair_accept[p] == 0)
                $display("  %4d  | REJECT   | %0d", p, pair_obs[p]);
            else
                $display("  %4d  | TIMEOUT  | -", p);
        end
        $display("============================================================");
        $display("  FINAL RESULTS");
        $display("============================================================");
        $display("  Total pairs     : %0d", NUM_PAIRS);
        $display("  Accepted (ALIGN): %0d", total_accepted);
        $display("  Rejected (SKIP) : %0d", total_rejected);
        $display("  Filtering rate  : %0d%%",
                 (total_rejected*100)/NUM_PAIRS);
        $display("============================================================");
        $finish;
